package clusterdata.datatypes;

public class TaskEvent {
    public long timestamp;      // microseconds
    public String missingInfo;
    public long jobId;
    public long taskIndex;
    public Long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double memoryRequest;
    public double diskRequest;
    public int differentMachine;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex,
                     Long machineId, int eventType, String userName, int schedulingClass,
                     int priority, double cpuRequest, double memoryRequest,
                     double diskRequest, int differentMachine) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskRequest = diskRequest;
        this.differentMachine = differentMachine;
    }

    public static TaskEvent fromString(String line) {
        String[] fields = line.split(",", -1);
        if (fields.length < 13) {
            return null;
        }

        TaskEvent event = new TaskEvent();
        event.timestamp = Long.parseLong(fields[0]);
        event.missingInfo = fields[1];
        event.jobId = Long.parseLong(fields[2]);
        event.taskIndex = Long.parseLong(fields[3]);
        event.machineId = fields[4].isEmpty() ? null : Long.parseLong(fields[4]);
        event.eventType = Integer.parseInt(fields[5]);
        event.userName = fields[6];
        event.schedulingClass = Integer.parseInt(fields[7]);
        event.priority = Integer.parseInt(fields[8]);
        event.cpuRequest = Double.parseDouble(fields[9]);
        event.memoryRequest = Double.parseDouble(fields[10]);
        event.diskRequest = Double.parseDouble(fields[11]);
        event.differentMachine = Integer.parseInt(fields[12]);

        return event;
    }

    @Override
    public String toString() {
        return timestamp + "," + missingInfo + "," + jobId + "," + taskIndex + "," +
               machineId + "," + eventType + "," + userName + "," + schedulingClass + "," +
               priority + "," + cpuRequest + "," + memoryRequest + "," + diskRequest + "," +
               differentMachine;
    }
}

