import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.time.Duration;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Read and parse task events
        DataStream<String> taskLines = env.readTextFile(taskInput);
        DataStream<TaskEvent> taskEvents = taskLines
                .map(new MapFunction<String, TaskEvent>() {
                    @Override
                    public TaskEvent map(String line) throws Exception {
                        return TaskEvent.fromString(line);
                    }
                })
                .filter(new FilterFunction<TaskEvent>() {
                    @Override
                    public boolean filter(TaskEvent event) throws Exception {
                        return event != null;
                    }
                });

        // Filter for SUBMIT events (eventType == 0)
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(new FilterFunction<TaskEvent>() {
                    @Override
                    public boolean filter(TaskEvent event) throws Exception {
                        return event.eventType == 0;
                    }
                })
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        // Group by jobId and apply session windows (10 minutes gap)
        DataStream<Tuple2<Long, Long>> sessionCounts = submitEvents
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .process(new ProcessWindowFunction<TaskEvent, Tuple2<Long, Long>, Long, TimeWindow>() {
                    @Override
                    public void process(Long jobId, Context context, Iterable<TaskEvent> elements,
                                        Collector<Tuple2<Long, Long>> out) throws Exception {
                        long count = 0;
                        for (TaskEvent event : elements) {
                            count++;
                        }
                        // Emit (jobId, count) for this session
                        out.collect(new Tuple2<>(jobId, count));
                    }
                });

        // Read and parse job events
        DataStream<String> jobLines = env.readTextFile(jobInput);
        DataStream<JobEvent> jobEvents = jobLines
                .map(new MapFunction<String, JobEvent>() {
                    @Override
                    public JobEvent map(String line) throws Exception {
                        return JobEvent.fromString(line);
                    }
                })
                .filter(new FilterFunction<JobEvent>() {
                    @Override
                    public boolean filter(JobEvent event) throws Exception {
                        return event != null;
                    }
                });

        // Filter for FINISH events (eventType == 4)
        DataStream<Long> finishedJobs = jobEvents
                .filter(new FilterFunction<JobEvent>() {
                    @Override
                    public boolean filter(JobEvent event) throws Exception {
                        return event.eventType == 4;
                    }
                })
                .map(new MapFunction<JobEvent, Long>() {
                    @Override
                    public Long map(JobEvent event) throws Exception {
                        return event.jobId;
                    }
                });

        // Find the maximum count per job
        DataStream<Tuple2<Long, Long>> maxSessionPerJob = sessionCounts
                .keyBy(tuple -> tuple.f0)
                .reduce(new ReduceFunction<Tuple2<Long, Long>>() {
                    @Override
                    public Tuple2<Long, Long> reduce(Tuple2<Long, Long> value1, Tuple2<Long, Long> value2) throws Exception {
                        // Keep the tuple with the larger count
                        if (value1.f1 > value2.f1) {
                            return value1;
                        } else {
                            return value2;
                        }
                    }
                });

        // Format output as (jobId,count)
        DataStream<String> output = maxSessionPerJob
                .map(new MapFunction<Tuple2<Long, Long>, String>() {
                    @Override
                    public String map(Tuple2<Long, Long> tuple) throws Exception {
                        return "(" + tuple.f0 + "," + tuple.f1 + ")";
                    }
                });

        // Write to output file
        output.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}

